/**
 * One keyset page of live (not archived) org ids, in id order. `afterId` is
 * exclusive: pass the last id of the previous page to continue, or `null` to
 * start from the top.
 */
export async function listLiveOrgIds(
  afterId: OrgId | null,
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(
      and(
        isNull(organizations.archivedAt),
        afterId === null ? undefined : gt(organizations.id, afterId),
      ),
    )
    .orderBy(asc(organizations.id))
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.id));
}

/**
 * Yields every live org id, fetching `pageSize` at a time, so a sweep covers
 * the whole tenant list however many workspaces there are.
 */
export async function* iterateLiveOrgIds(
  pageSize: number,
): AsyncGenerator<OrgId> {
  const size = Math.max(1, pageSize);
  let afterId: OrgId | null = null;

  for (;;) {
    const page = await listLiveOrgIds(afterId, size);
    for (const orgId of page) yield orgId;
    if (page.length < size) return;
    afterId = page[page.length - 1] ?? null;
  }
}

/** Every org the user still holds a live membership in. */

