import { and, asc, count, eq, isNull, sql } from "drizzle-orm";
import {
  attachments,
  getDb,
  issues,
  members,
  organizations,
  organizationUsage,
  projects,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUsage } from "./_mappers";
import { brandId } from "./_mappers";
import type { IsoTimestamp, OrgId } from "@/types/common";
import type { OrganizationUsage } from "@/types/organization";

const BYTES_PER_MB = 1024 * 1024;

/**
 * `measured_at` for a counter row nobody has recounted yet. It sorts before any
 * real recount, so the rollup queue picks that workspace up first.
 */
const NEVER_MEASURED = toIsoTimestamp(new Date(0));

/**
 * Stamps a recount so it is strictly later than the previous one in this
 * process. The rollup queue orders on `measured_at`; two recounts in the same
 * millisecond would tie and let the newer one sort ahead of an older one.
 */
let lastStampMs = 0;

function nextMeasuredAt(): IsoTimestamp {
  lastStampMs = Math.max(Date.now(), lastStampMs + 1);
  return toIsoTimestamp(new Date(lastStampMs));
}

/**
 * Reads the cached counters, materialising a zeroed row the first time an org
 * is asked about. A limit check must never fail because the rollup has not run.
 */
export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
  const row = getDb()
    .select()
    .from(organizationUsage)
    .where(eq(organizationUsage.orgId, orgId))
    .get();

  if (row) return toUsage(row);

  const created = getDb()
    .insert(organizationUsage)
    .values({ orgId, measuredAt: NEVER_MEASURED })
    .returning()
    .get();

