import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const PAST = "2026-01-01T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});
afterAll(() => cleanup());

describe("scratch: coverage", () => {
  it("overdue job reaches every live org, skips archived ones", async () => {
    const orgs: string[] = [];
    for (let i = 0; i < 55; i += 1) {
      const t = await createTenant(`scratch-od-${String(i).padStart(3, "0")}`);
      orgs.push(t.org.id);
      const number = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
      await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title: "late", dueAt: PAST }), t.userIds.owner, number);
    }
    await orgRepo.archiveOrg(orgs[0] as never);

    const seen: string[] = [];
    const off: Unsubscribe = subscribe("issue.overdue", (p) => {
      seen.push(p.orgId);
    });
    const result = await runOverdueIssueJob(NOW);
    off();

    expect(seen).toHaveLength(54);
    expect(seen).not.toContain(orgs[0]);
    expect(new Set(seen).size).toBe(54);
    expect(result.processed).toBe(54);

    const again = await runOverdueIssueJob(NOW);
    expect(again.processed).toBe(0);
  });

  it("iterateLiveOrgIds pages through all live orgs", async () => {
    const all: string[] = [];
    for await (const id of orgRepo.iterateLiveOrgIds(7)) all.push(id);
    const listed = await orgRepo.listLiveOrgIds(null, 1000);
    expect(all).toEqual([...listed]);
    expect(all.length).toBeGreaterThanOrEqual(55);
    expect(all).toEqual([...all].sort());
  });

  it("rollup queue: never-measured first, recount moves to back, deltas don't reorder", async () => {
    const a = await createTenant("scratch-q-a");
    const b = await createTenant("scratch-q-b");
    const c = await createTenant("scratch-q-c");

    // Recount c, then a, then b — same-millisecond recounts must still order.
    await usageRepo.recomputeUsage(c.org.id);
    await usageRepo.recomputeUsage(a.org.id);
    await usageRepo.recomputeUsage(b.org.id);

    const before = await usageRepo.listOrgIdsForRollup(1000);
    const posC = before.indexOf(c.org.id as never);
    const posA = before.indexOf(a.org.id as never);
    const posB = before.indexOf(b.org.id as never);
    expect(posC).toBeLessThan(posA);
    expect(posA).toBeLessThan(posB);

    // A delta must not move a workspace in the queue.
    await usageRepo.incrementUsage(c.org.id, { seatsUsed: 1 });
    const afterDelta = await usageRepo.listOrgIdsForRollup(1000);
    expect(afterDelta).toEqual(before);

    // A recount moves to the back.
    await usageRepo.recomputeUsage(c.org.id);
    const afterRecount = await usageRepo.listOrgIdsForRollup(1000);
    expect(afterRecount.at(-1)).toBe(c.org.id);
  });

  it("rollup skips deleted orgs and recounts at most the batch", async () => {
    const list = await usageRepo.listOrgIdsForRollup(25);
    expect(list.length).toBeLessThanOrEqual(25);
    const result = await runUsageRollupJob(NOW);
    expect(result.processed).toBe(25);
    expect(result.failed).toBe(0);
  });

  it("cleanup walks every page of archived issues", async () => {
    const t = await createTenant("scratch-cleanup");
    const actor = t.actors.owner;
    for (let i = 0; i < 105; i += 1) {
      const issue = await issueService.createIssue(actor, issueInput(t.org.id, t.project.id, { title: `c${i}` }));
      await issueService.archiveIssue(actor, t.org.id, issue.id);
    }
    const future = new Date("2030-01-01T00:00:00.000Z");
    const result = await runCleanupArchivedJob(future);
    expect(result.processed).toBeGreaterThanOrEqual(105);
    expect(result.failed).toBe(0);
  });
});

